// Pure, deterministic traces: the UI only renders snapshots and never simulates algorithms.
export const labs={};
const clone=x=>structuredClone(x);
const field=(key,label,value,hint='')=>({key,label,value:String(value),hint});
const values=field('values','初始元素','12, 24, 36, 48, 60','逗号或空格分隔；最多 16 个数，可留空');
const pos=field('position','位序 i','3','位序从 1 开始，与数组下标 i−1 区分');
const val=field('value','元素 x','30');
const add=(topic,key,label,fields,code,run)=>{(labs[topic]??=[]).push({key,label,fields,code:code.split('\n'),run});};
export function numbers(s,max=16){const a=String(s).trim()?String(s).trim().split(/[,，\s]+/).map(Number):[];if(a.length>max||a.some(x=>!Number.isFinite(x)||Math.abs(x)>99999))throw Error(`请输入最多 ${max} 个有限数，绝对值不超过 99999。`);return a;}
const integer=(v,min,max,label='参数')=>{const n=Number(v);if(!String(v).trim()||!Number.isInteger(n)||n<min||n>max)throw Error(`${label}须为 ${min}～${max} 的整数。`);return n;};
const scalar=v=>{if(!String(v).trim()||!Number.isFinite(Number(v))||Math.abs(Number(v))>99999)throw Error('请输入绝对值不超过 99999 的有限数。');return Number(v);};
function trace(base){const frames=[];return {frames,push:(note,extra={})=>frames.push(clone({...base,note,line:0,...extra}))};}
const arr=(a,extra={})=>({kind:'array',array:a,...extra});
function listDiagram(a,type='linked',active=[],done=[]){const n=a.length;const nodes=[{id:'head',label:'头结点',x:55,y:150,sub:'不存数据'}];a.forEach((x,i)=>nodes.push({id:String(i),label:String(x),x:150+i*85,y:150,sub:type==='static-list'?`地址 ${i+1}`:`结点 ${i+1}`}));const edges=[];if(n)edges.push({from:'head',to:'0'});if(n&&type==='doubly')edges.push({from:'0',to:'head',reverse:true});for(let i=0;i<n-1;i++){edges.push({from:String(i),to:String(i+1)});if(type==='doubly')edges.push({from:String(i+1),to:String(i),reverse:true});}if(type==='circular')edges.push({from:n?String(n-1):'head',to:'head',curve:true,label:'回到头结点'});return {kind:'graph',nodes,edges,width:Math.max(760,190+n*85),height:300,active:active.map(String),done:done.map(String),caption:type==='circular'?'循环结束条件是再次遇到 head':type==='static-list'?'用数组下标充当游标；下标 0 为头结点，−1 表示空游标':type==='doubly'?'实线箭头为 next / prior，头结点不计入位序':'头结点不计入位序；最后一个结点的 next = NULL'};}
function linearTrace(p,op,type='sequence'){
 const a=numbers(p.values), t=trace({});const show=(note,extra={})=>t.push(note,{...(type==='sequence'?arr([...a]):listDiagram(a,type)),...extra});
 show('先观察初始结构。逻辑位序从 1 开始；数组下标从 0 开始。',{vars:{length:a.length}});
 if(op==='insert'){
  const i=integer(p.position,1,a.length+1,'插入位序')-1,x=scalar(p.value);if(a.length===16)throw Error('演示上限为 16 个元素，请先减少初始元素。');
  if(type==='sequence'){a.push('·');for(let j=a.length-2;j>=i;j--){a[j+1]=a[j];a[j]='·';show(`将下标 ${j} 的元素右移到 ${j+1}，从后向前移动以免覆盖。`,{active:[j,j+1],line:1,vars:{j,i:i+1}});}a[i]=x;show(`把 ${x} 写入下标 ${i}，长度加 1。`,{active:[i],line:2,result:[...a]});}
  else{for(let j=0;j<i;j++)show(`沿 next 找到第 ${j+1} 个结点。`,{active:[String(j)],line:1});show(`保存后继，在位序 ${i+1} 前插入 ${x}。先让新结点指向后继，再修改前驱。`,{active:[i?String(i-1):'head'],line:2,vars:{'前驱':i?a[i-1]:'head','后继':a[i]??'NULL','新结点':x}});a.splice(i,0,x);show(type==='doubly'?'next 与 prior 关系均已更新；边界结点按需处理。':'连接完成：新结点已进入链表。',{active:[String(i)],line:3,result:[...a]});}
 }else if(op==='delete'){
  const i=integer(p.position,1,a.length,'删除位序')-1,x=a[i];
  if(type==='sequence'){a[i]='·';show(`保存被删元素 ${x}。`,{active:[i],line:1});for(let j=i+1;j<a.length;j++){a[j-1]=a[j];a[j]='·';show(`将下标 ${j} 的元素左移到 ${j-1}。`,{active:[j-1,j],line:2});}a.pop();}
  else{for(let j=0;j<=i;j++)show(`定位待删结点 ${x} 及其前驱。`,{active:[String(j)],line:1});show(`让前驱绕过 ${x} 指向后继，再释放待删结点。`,{active:[String(i)],line:2,vars:{'后继':a[i+1]??(type==='circular'?'head':'NULL')}});a.splice(i,1);}
  show(`删除完成，返回 ${x}。长度变为 ${a.length}。`,{line:3,result:[...a],vars:{deleted:x,length:a.length}});
 }else if(op==='find'){
  const x=scalar(p.value);let found=-1;for(let i=0;i<a.length;i++){show(`比较当前元素 ${a[i]} 与目标 ${x}。`,{active:[type==='sequence'?i:String(i)],line:1,vars:{'位序':i+1}});if(a[i]===x){found=i;break;}}
  show(found<0?'查找失败，遍历到末尾仍未找到。':`找到第一次出现的位置：位序 ${found+1}，下标 ${found}。`,{done:found<0?[]:[type==='sequence'?found:String(found)],line:2,result:found+1});
 }else if(op==='reverse'){
  if(type==='sequence'){for(let l=0,r=a.length-1;l<r;l++,r--){[a[l],a[r]]=[a[r],a[l]];show(`交换下标 ${l} 与 ${r} 的元素，两个指针向中间收拢。`,{active:[l,r],line:1,vars:{left:l,right:r}});}}
  else{const original=[...a];let previous=null;for(let i=0;i<a.length;i++){const nodes=original.map((v,j)=>({id:String(j),label:String(v),x:90+j*85,y:150,sub:j===i?'cur':j===i-1?'prev':j===i+1?'next':''}));const edges=[];for(let j=0;j<original.length;j++){if(j<=i&&j>0)edges.push({from:String(j),to:String(j-1)});if(j>i&&j+1<original.length)edges.push({from:String(j),to:String(j+1)});}t.push(`保存 next=${original[i+1]??'NULL'}；将 cur.next 改指 prev=${previous??'NULL'}；随后推进指针。`,{kind:'graph',nodes,edges,width:Math.max(760,a.length*85+100),active:[String(i)],line:1,vars:{prev:previous??'NULL',cur:original[i],next:original[i+1]??'NULL'}});previous=original[i];}a.reverse();}
  show('反转完成。空表和单元素表无需交换。',{line:2,result:[...a]});
 }else if(op==='dedupe'){
  if(a.some((v,i)=>i&&a[i-1]>v))throw Error('有序去重要求输入为非递减序列。');let k=0;const original=[...a];for(let j=0;j<original.length;j++){if(!k||original[j]!==a[k-1])a[k++]=original[j];show(`扫描 ${original[j]}，有效前缀长度为 ${k}。只在与前一个保留值不同时写入。`,{active:[j],done:Array.from({length:k},(_,i)=>i),line:1,vars:{read:j,write:k}});}a.length=k;show('截去无效后缀，完成原地去重。',{line:2,result:[...a]});
 }else if(op==='kth'){
  const k=integer(p.position,1,a.length,'倒数 k');let fast=0,slow=0;for(;fast<k;fast++)show('先让 fast 向前走 k 步。',{active:[String(fast)],line:1,vars:{fast:fast+1,slow:1,k}});for(;fast<a.length;fast++,slow++)show('fast 与 slow 同步前进，始终保持 k 个位置的距离。',{active:[String(fast),String(slow)],line:2,vars:{fast:fast+1,slow:slow+1,k}});show(`fast 到达 NULL，slow 指向倒数第 ${k} 个元素 ${a[slow]}。`,{done:[String(slow)],line:3,result:a[slow]});
 }else if(op==='merge'){
  const b=numbers(p.other);if([...a,...b].length>24)throw Error('合并演示总元素数不能超过 24。');if([a,b].some(x=>x.some((v,i)=>i&&x[i-1]>v)))throw Error('归并要求两表均非递减。');let i=0,j=0;const c=[];while(i<a.length||j<b.length){if(j===b.length||(i<a.length&&a[i]<=b[j]))c.push(a[i++]);else c.push(b[j++]);t.push(`从两表尚未处理的头部取较小值 ${c.at(-1)}。`,{kind:'rows',rows:[{label:'A',values:a,active:[i]},{label:'B',values:b,active:[j]},{label:'结果',values:c}],line:1,vars:{i,j}});}t.push('归并完成，保持非递减顺序。',{...arr(c),line:2,result:c});
 }
 return t.frames;
}
for(const topic of ['sequence','linked','doubly','circular','static-list']){
 add(topic,'insert','插入元素',[values,pos,val],'检查位序与容量\n定位前驱 / 将后缀右移\n保存后继 / 写入新元素\n连接新结点并更新长度',p=>linearTrace(p,'insert',topic));
 add(topic,'delete','删除元素',[values,pos],'检查删除位序\n定位并保存待删元素\n左移后缀 / 修改前后链接\n长度减一，返回被删值',p=>linearTrace(p,'delete',topic));
 add(topic,'find','按值查找',[values,val],'从表头开始\n逐个比较元素与 x\n返回首个匹配位序，失败返回 0',p=>linearTrace(p,'find',topic));
}
for(const topic of ['sequence','linked'])add(topic,'reverse',topic==='sequence'?'双指针反转':'三指针反转',[values],'准备首尾指针 / prev、cur、next\n交换两端 / 保存后继后反转 next\n完成反转，更新头指针',p=>linearTrace(p,'reverse',topic));
add('sequence','dedupe','有序表去重',[field('values','非递减序列','2, 2, 5, 5, 5, 8, 9')],'初始化写指针 k=0\n扫描，遇到新值就写入有效前缀\n将长度设为 k',p=>linearTrace(p,'dedupe'));
add('sequence','merge','合并两个有序表',[field('values','有序表 A','1, 4, 7'),field('other','有序表 B','2, 4, 9')],'i=j=0\n选择 A[i]、B[j] 中较小者\n收集剩余元素',p=>linearTrace(p,'merge'));
add('linked','kth','例题：倒数第 k 个结点',[values,field('position','倒数 k','2')],'初始化 fast、slow\nfast 先走 k 步\n两个指针同步前进\nfast 为空时返回 slow',p=>linearTrace(p,'kth','linked'));

function stackTrace(p,op){const a=numbers(p.values,10),capacity=integer(p.capacity??10,1,12,'容量'),t=trace({});if(a.length>capacity)throw Error('初始元素超过容量。');const show=(s,e={})=>t.push(s,{...arr([...a]),orientation:'stack',caption:'栈底在左，栈顶在右；顺序栈 top = length − 1',vars:{top:a.length-1,length:a.length,capacity},...e});show('初始栈。只有栈顶一端允许插入和删除。');if(op==='push'){const x=scalar(p.value);if(a.length===capacity)show('栈满：拒绝入栈，原状态保持不变。',{line:1,result:false});else{a.push(x);show(`top 先加一，再把 ${x} 放入栈顶。`,{active:[a.length-1],line:2,result:a});}}else{if(!a.length)show('栈空：没有可弹出的元素。',{line:1,result:false});else{const x=a.pop();show(`返回栈顶 ${x}，top 减一。`,{line:2,result:x});}}return t.frames;}
for(const op of ['push','pop'])add('stack',op,op==='push'?'入栈 Push':'出栈 Pop',[field('values','栈底 → 栈顶','10, 20, 30'),...(op==='push'?[val]:[]),field('capacity','容量','6')],'观察 top\n检查上溢 / 下溢\n入栈 ++top / 出栈 top--',p=>stackTrace(p,op));
add('stack','shared','共享栈相向生长',[field('left','左栈（底→顶）','1, 2'),field('right','右栈（底→顶）','9, 8'),field('capacity','总容量','8'),field('side','入哪一栈：L 或 R','L'),val],'top1=-1，top2=capacity\n若 top1+1==top2 则栈满\n向选定一侧的栈顶写入',p=>{const l=numbers(p.left),r=numbers(p.right),c=integer(p.capacity,2,12,'总容量'),side=p.side.trim().toUpperCase();if(!['L','R'].includes(side)||l.length+r.length>c)throw Error('侧别须为 L/R，初始总元素数不能超过容量。');const t=trace({});const show=(note,line=0)=>t.push(note,{...arr([...l,...Array(c-l.length-r.length).fill('·'),...r.toReversed()]),vars:{top1:l.length-1,top2:c-r.length},line});show('两个栈分别从数组两端向中间生长。');if(l.length+r.length===c)show('top1+1=top2：空间已全部使用，不能入栈。',1);else{(side==='L'?l:r).push(scalar(p.value));show('只移动所选栈的栈顶；两栈共用中间的空闲空间。',2);}return t.frames;});

function queueTrace(p,op){const a=numbers(p.values,10),c=integer(p.capacity??6,2,12,'数组容量'),front=integer(p.front??0,0,c-1,'front');if(a.length>c-1)throw Error('本循环队列牺牲一个单元，最多存 capacity−1 个元素。');let f=front,r=(front+a.length)%c;const slots=Array(c).fill('·');a.forEach((v,i)=>slots[(f+i)%c]=v);const t=trace({});const show=(s,e={})=>{const nodes=slots.map((v,i)=>({id:String(i),label:String(v),x:380+125*Math.cos(2*Math.PI*i/c-Math.PI/2),y:180+125*Math.sin(2*Math.PI*i/c-Math.PI/2),sub:`${i}${i===f?' · front':''}${i===r?' · rear':''}`}));t.push(s,{kind:'graph',nodes,edges:slots.map((_,i)=>({from:String(i),to:String((i+1)%c)})),height:375,vars:{front:f,rear:r,length:(r-f+c)%c,capacity:c},caption:'front 指向队头；rear 指向下一次入队位置；保留一个空单元区分空与满',...e});};show('循环队列的下标通过取模回到数组开头。');if(op==='enqueue'){if((r+1)%c===f)show('队满：(rear+1)%capacity == front，拒绝入队。',{line:1,result:false});else{slots[r]=scalar(p.value);show(`将 ${slots[r]} 写入 rear=${r}。`,{active:[String(r)],line:2});r=(r+1)%c;show('rear = (rear+1) % capacity。',{line:3,result:slots.filter(v=>v!=='·')});}}else if(f===r)show('队空：front == rear，拒绝出队。',{line:1,result:false});else{const x=slots[f];slots[f]='·';f=(f+1)%c;show(`返回 ${x}；front = (front+1) % capacity。`,{line:3,result:x});}return t.frames;}
for(const op of ['enqueue','dequeue'])add('queue',op,op==='enqueue'?'循环队列入队':'循环队列出队',[field('values','队头 → 队尾','10, 20, 30'),field('capacity','数组容量','6'),field('front','front 初值','4'),...(op==='enqueue'?[val]:[])],'确定 front、rear\n判满 / 判空\n写入或取出队头元素\n通过取模更新指针',p=>queueTrace(p,op));
for(const op of ['push-front','push-back','pop-front','pop-back'])add('deque',op,{'push-front':'队头入队','push-back':'队尾入队','pop-front':'队头出队','pop-back':'队尾出队'}[op],[values,...(op.startsWith('push')?[val]:[])],'标记队头与队尾\n在选定端插入 / 删除\n保持其他元素的相对顺序',p=>{const a=numbers(p.values),t=trace({});t.push('双端队列允许在两端操作；这里展示不受限的双端队列。',{...arr(a),vars:{front:a[0]??'空',back:a.at(-1)??'空'}});let result;if(op.startsWith('push')){if(a.length>=16)throw Error('演示最多 16 个元素。');op==='push-front'?a.unshift(scalar(p.value)):a.push(scalar(p.value));result=[...a];}else result=op==='pop-front'?a.shift():a.pop();t.push(result===undefined?'队空，删除失败。':'操作完成。头端在左，尾端在右。',{...arr(a),line:1,result:result??false,vars:{front:a[0]??'空',back:a.at(-1)??'空'}});return t.frames;});
add('stack-apps','brackets','括号匹配',[field('text','括号序列','{[()]}()','只支持 () [] {}，最长 30 个字符')],'初始化空栈\n左括号入栈\n右括号与栈顶匹配并弹出\n扫描结束且栈空才匹配',p=>{const text=p.text.trim();if(text.length>30||/[^()[\]{}]/.test(text))throw Error('只支持最多 30 个括号字符。');const t=trace({}),s=[],pair={')':'(',']':'[','}':'{'};t.push('遇到最近打开的括号，应最先闭合：用栈保存左括号。',arr(s));for(let i=0;i<text.length;i++){const c=text[i];if('([{'.includes(c)){s.push(c);t.push(`读入 ${c}：左括号入栈。`,{...arr(s),line:1,vars:{i,char:c}});}else{if(s.at(-1)!==pair[c]){t.push(`读入 ${c}，与栈顶 ${s.at(-1)??'空'} 不匹配，立即失败。`,{...arr(s),line:2,vars:{i},result:false});return t.frames;}s.pop();t.push(`读入 ${c}，与栈顶匹配，弹出左括号。`,{...arr(s),line:2,vars:{i,char:c}});}}t.push(s.length?'扫描结束，但还有未闭合的左括号。':'扫描结束且栈空：所有括号匹配。',{...arr(s),line:3,result:!s.length});return t.frames;});
add('stack-apps','postfix','后缀表达式求值',[field('text','后缀表达式','3 4 + 2 * 5 -','数字与运算符用空格分隔，支持 + − * /')],'准备操作数栈\n数字入栈\n先弹右操作数 b，再弹左操作数 a\n计算 a op b 并入栈，最终只余一个值',p=>{const ts=p.text.trim().split(/\s+/);if(ts.length>30)throw Error('最多 30 个 token。');const s=[],t=trace({});t.push('后缀表达式无需括号或运算优先级比较。',arr(s));for(const c of ts){if(c!==''&&Number.isFinite(Number(c))){s.push(scalar(c));t.push(`操作数 ${c} 入栈。`,{...arr(s),line:1});}else{if(!['+','-','*','/'].includes(c)||s.length<2)throw Error(`非法 token 或操作数不足：${c}`);const b=s.pop(),a=s.pop();if(c==='/'&&b===0)throw Error('除数不能为 0。');const v=c==='+'?a+b:c==='-'?a-b:c==='*'?a*b:a/b;if(!Number.isFinite(v))throw Error('计算溢出。');s.push(v);t.push(`先弹 b=${b}，再弹 a=${a}；${a} ${c} ${b} = ${v}。`,{...arr(s),line:2,vars:{a,b,op:c}});}}if(s.length!==1)throw Error('表达式不完整：最终必须恰有一个结果。');t.push(`结果为 ${s[0]}。`,{...arr(s),line:3,result:s[0]});return t.frames;});
add('stack-apps','recursion','递归调用栈：阶乘',[field('n','n','5','0～9')],'factorial(n)\n若 n≤1，返回 1\n压栈并调用 factorial(n−1)\n返回时计算 n × 子调用结果',p=>{const n=integer(p.n,0,9,'n'),t=trace({}),s=[];function f(k){s.push(`f(${k})`);t.push(`进入 f(${k})，调用信息入栈。`,{...arr(s),line:2,vars:{n:k}});let v;if(k<=1){v=1;t.push('到达递归出口，返回 1。',{...arr(s),line:1});}else v=k*f(k-1);s.pop();t.push(`f(${k}) 返回 ${v}，栈帧弹出。`,{...arr(s),line:3,vars:{returned:v},result:v});return v;}f(n);return t.frames;});

for(const mode of ['row','symmetric','lower','upper','band'])add('matrix',mode,{row:'二维数组寻址',symmetric:'对称矩阵压缩',lower:'下三角矩阵压缩',upper:'上三角矩阵压缩',band:'三对角矩阵压缩'}[mode],[field('n','矩阵阶数 n','5','2～6'),field('i','行号 i','3','从 1 开始'),field('j','列号 j','2','从 1 开始')], '识别矩阵类型与下标约定\n确定哪些元素需要保存\n计算压缩数组下标 k（从0开始）\n地址 = base + k × sizeof(Element)',p=>{const n=integer(p.n,2,6,'n'),i=integer(p.i,1,n,'i'),j=integer(p.j,1,n,'j'),t=trace({});let k,formula;const m=Array.from({length:n},(_,r)=>Array.from({length:n},(_,c)=>mode==='symmetric'?10*Math.max(r+1,c+1)+Math.min(r+1,c+1):mode==='lower'&&c>r?'c':mode==='upper'&&r>c?'c':mode==='band'&&Math.abs(r-c)>1?0:10*(r+1)+c+1));const compressed=[];for(let r=0;r<n;r++)for(let c=0;c<n;c++)if(mode==='row'||(mode==='symmetric'||mode==='lower')&&r>=c||mode==='upper'&&r<=c||mode==='band'&&Math.abs(r-c)<=1)compressed.push(m[r][c]);if(mode==='lower'||mode==='upper')compressed.push('c');t.push('行号、列号从 1 开始，压缩数组下标从 0 开始。',{kind:'matrix',matrix:m,caption:'数值采用 10×行号+列号 便于跟踪；c 表示三角区域外的相同常量'});if(mode==='row'){k=(i-1)*n+j-1;formula='(i−1)×n + (j−1)';}if(mode==='symmetric'){const a=Math.max(i,j),b=Math.min(i,j);k=a*(a-1)/2+b-1;formula='a(a−1)/2+b−1，其中 a=max(i,j)，b=min(i,j)';}if(mode==='lower'){k=i>=j?i*(i-1)/2+j-1:n*(n+1)/2;formula=i>=j?'i(i−1)/2+j−1':'n(n+1)/2（常量专用位置）';}if(mode==='upper'){k=i<=j?(i-1)*(2*n-i+2)/2+j-i:n*(n+1)/2;formula=i<=j?'(i−1)(2n−i+2)/2+j−i':'n(n+1)/2（常量专用位置）';}if(mode==='band'){k=Math.abs(i-j)<=1?2*i+j-3:-1;formula=k<0?'带外元素恒为 0，无需存储':'2i+j−3';}t.push(`选中 a[${i},${j}] = ${m[i-1][j-1]}。`,{kind:'matrix',matrix:m,cell:[i-1,j-1],line:1});t.push(`k = ${formula}${k>=0?` = ${k}`:''}。`,{kind:'rows',rows:[{label:'压缩数组 B',values:compressed,active:[k]}],line:2,vars:{i,j,k:k<0?'无需存储':k,'存储单元':compressed.length},result:k});return t.frames;});
add('matrix','sparse','稀疏矩阵：三元组与转置',[field('matrix','矩阵（分号分行）','0,0,7; 5,0,0; 0,9,0','最多 6×6；每行逗号分隔')],'扫描所有非零项\n保存 (行,列,值)\n交换每个三元组的行列\n按新行、新列排序得到转置',p=>{const m=p.matrix.split(/[;；\n]/).filter(x=>x.trim()).map(x=>numbers(x,6));if(!m.length||m.length>6||!m[0].length||m.some(r=>r.length!==m[0].length))throw Error('请输入等长的矩形矩阵，最多 6×6。');const t=trace({}),triples=[];t.push('零元素不占用三元组存储；另需保存矩阵的行数、列数和非零元素数。',{kind:'matrix',matrix:m});m.forEach((row,i)=>row.forEach((v,j)=>{if(v!==0){triples.push([i+1,j+1,v]);t.push(`记录非零项 (${i+1}, ${j+1}, ${v})。`,{kind:'matrix',matrix:m,cell:[i,j],line:1,table:{headers:['行','列','值'],rows:triples}});}}));const trans=triples.map(([i,j,v])=>[j,i,v]).sort((a,b)=>a[0]-b[0]||a[1]-b[1]);t.push('交换行列后重新按行序排列。演示使用排序转置；快速转置可通过列计数定位。',{kind:'matrix',matrix:m[0].map((_,j)=>m.map(row=>row[j])),line:3,table:{headers:['转置后行','转置后列','值'],rows:trans},result:trans});return t.frames;});

const textField=field('text','主串 S','ababcabcacbab','最多 40 个字符');
const patternField=field('pattern','模式串 T','abcac','1～16 个字符');
const chars=(v,max=40)=>{const a=Array.from(v);if(a.length>max)throw Error(`最多 ${max} 个字符。`);return a;};
add('string','substring','求子串',[textField,field('position','起始位序','3'),field('length','长度','5')],'检查位置与长度\n从 pos−1 起复制 len 个字符\n返回子串',p=>{const a=chars(p.text),i=integer(p.position,1,a.length+1,'起始位序')-1,n=integer(p.length,0,a.length-i,'长度'),t=trace({});t.push('串是字符序列；本例位序从 1 开始。',arr(a));let out=[];for(let j=0;j<n;j++){out.push(a[i+j]);t.push(`复制第 ${i+j+1} 个字符 ${a[i+j]}。`,{kind:'rows',rows:[{label:'S',values:a,active:[i+j]},{label:'子串',values:out}],line:1});}t.push(`子串为「${out.join('')}」。`,{...arr(out),line:2,result:out.join('')});return t.frames;});
add('string','concat','连接两个串',[textField,field('other','另一串','XYZ')],'确定结果长度\n复制第一个串\n在末尾接上第二个串',p=>{const a=chars(p.text),b=chars(p.other),t=trace({});t.push('连接保留两个串内字符的原有次序。',{kind:'rows',rows:[{label:'S',values:a},{label:'T',values:b}]});t.push('先复制 S。',{...arr(a),line:1});t.push('再接上 T。',{...arr([...a,...b]),active:b.map((_,i)=>a.length+i),line:2,result:a.join('')+b.join('')});return t.frames;});
add('string','compare','字典序比较',[field('text','S','abc'),field('other','T','abd')],'从第一个字符开始\n遇到第一个不同字符即决定大小\n公共前缀相同则短串更小',p=>{const a=chars(p.text),b=chars(p.other),t=trace({});let r=0;for(let i=0;i<Math.min(a.length,b.length);i++){t.push(`比较 S[${i}] 与 T[${i}]。`,{kind:'rows',rows:[{label:'S',values:a,active:[i]},{label:'T',values:b,active:[i]}],line:1});if(a[i]!==b[i]){r=a[i].codePointAt(0)<b[i].codePointAt(0)?-1:1;break;}}if(!r)r=Math.sign(a.length-b.length);t.push(r===0?'两串相等。':r<0?'S 的字典序小于 T。':'S 的字典序大于 T。',{kind:'rows',rows:[{label:'S',values:a},{label:'T',values:b}],line:2,caption:'演示按 Unicode 码点比较，ASCII 字符与教材通常采用的编码顺序一致。',result:r});return t.frames;});
export function prefix(a){const pi=Array(a.length).fill(0);for(let i=1;i<a.length;i++){let j=pi[i-1];while(j>0&&a[i]!==a[j])j=pi[j-1];if(a[i]===a[j])j++;pi[i]=j;}return pi;}
function stringMatch(p,mode){const a=chars(p.text),b=chars(p.pattern,16);if(!b.length)throw Error('模式串不能为空。');const t=trace({}),pi=prefix(b);const show=(note,i,j,line=0,extra={})=>t.push(note,{kind:'rows',rows:[{label:'主串 S',values:a,active:[i]},{label:'模式 T',values:b,active:[j],offset:Math.max(0,i-j)},{label:'前缀表 π',values:pi}],line,vars:{i,j,'对齐起点(下标)':i-j},...extra});show('i、j 均从 0 开始。匹配成功返回起始位序（下标+1）。',0,0);if(mode==='naive'){for(let s=0;s<=a.length-b.length;s++){let j=0;while(j<b.length){show(`比较 S[${s+j}]=${a[s+j]} 与 T[${j}]=${b[j]}。`,s+j,j,1);if(a[s+j]!==b[j]){show('失配：主串起点右移一位，模式指针回到 0。',s+1,0,2);break;}j++;}if(j===b.length){show(`匹配成功，起始位序为 ${s+1}。`,s+j,j,3,{result:s+1});return t.frames;}}}else{let j=0;for(let i=0;i<a.length;i++){while(j>0&&a[i]!==b[j]){show(`失配：已匹配长度 ${j} 回退到 π[${j-1}]=${pi[j-1]}，主串 i 不回退。`,i,j,2);j=pi[j-1];}show(`比较 S[${i}]=${a[i]} 与 T[${j}]=${b[j]}。`,i,j,1);if(a[i]===b[j])j++;if(j===b.length){show(`匹配成功，起始位序为 ${i-b.length+2}。`,i+1,j,3,{result:i-b.length+2});return t.frames;}}}show('主串已扫描结束，没有完整匹配，返回 0。',a.length,0,3,{result:0});return t.frames;}
for(const mode of ['naive','kmp'])add('kmp',mode,mode==='naive'?'朴素模式匹配':'KMP 模式匹配',[textField,patternField],'初始化 i、j\n字符相同则推进\n失配：朴素法重试起点 / KMP 回退 j\n匹配完模式则返回起始位序',p=>stringMatch(p,mode));
add('kmp','prefix','构造 π / next / nextval',[patternField],'π[i]：T[0..i] 的最长相等真前后缀长度\n失配时沿 π 链回退\n匹配则长度加一\n换算教材1起始 next，并跳过重复比较得到 nextval',p=>{const a=chars(p.pattern,16);if(!a.length)throw Error('模式串不能为空。');const pi=Array(a.length).fill(0),t=trace({});t.push('π 数组下标从 0 开始，π[0]=0。',arr(a));for(let i=1;i<a.length;i++){let j=pi[i-1];while(j>0&&a[i]!==a[j]){t.push(`T[${i}] 与 T[${j}] 不同；长度从 ${j} 回退到 ${pi[j-1]}。`,{kind:'rows',rows:[{label:'T',values:a,active:[i,j]},{label:'π',values:pi}],line:1});j=pi[j-1];}if(a[i]===a[j])j++;pi[i]=j;t.push(`π[${i}] = ${j}，只考虑真前缀和真后缀。`,{kind:'rows',rows:[{label:'T',values:a,active:[i]},{label:'π',values:pi,active:[i]}],line:2});}const next=a.map((_,i)=>i===0?0:pi[i-1]+1),nv=[0];for(let i=1;i<a.length;i++){const k=next[i]-1;nv[i]=a[i]===a[k]?nv[k]:next[i];}t.push('教材 next 的位置 j 从 1 开始：next[1]=0；j≥2 时 next[j]=π[j−2]+1。nextval 继续跳过相同字符。',{kind:'rows',rows:[{label:'模式位置 j',values:a.map((_,i)=>i+1)},{label:'T',values:a},{label:'π (0起始)',values:pi},{label:'next (1起始)',values:next},{label:'nextval',values:nv}],line:3,result:{pi,next,nextval:nv}});return t.frames;});

const treeField=field('tree','二叉树顺序槽位','A B C D E # F','0起始槽位；孩子为2i+1/2i+2；#为空，最多15个槽位');
function readTree(s){const a=s.trim()?s.trim().split(/[,，\s]+/):[];if(a.length>15||a.some(x=>x.length>4))throw Error('最多 15 个槽位；每个结点标签最多 4 个字符。');for(let i=1;i<a.length;i++)if(a[i]!=='#'&&(!a[Math.floor((i-1)/2)]||a[Math.floor((i-1)/2)]==='#'))throw Error('非空结点不能有空双亲，请按完整二叉树槽位填写 #。');return a.map(v=>v==='#'?null:v);}
function treeView(a,active=[],done=[],extraEdges=[]){const nodes=[],edges=[];a.forEach((v,i)=>{if(v===null)return;const level=Math.floor(Math.log2(i+1)),start=2**level-1,x=760*(i-start+0.5)/2**level;nodes.push({id:String(i),label:v,x,y:55+level*85,sub:`槽位 ${i}`});if(i)edges.push({from:String(Math.floor((i-1)/2)),to:String(i),label:i%2?'L':'R'});});return {kind:'graph',nodes,edges:[...edges,...extraEdges],height:360,active:active.map(String),done:done.map(String)};}
add('binary-tree','properties','性质与存储槽位',[treeField],'扫描二叉树结点\n统计各结点的度\n验证 n₀=n₂+1（非空树）\n检查完全二叉树：有效槽位之间不能有空洞',p=>{const a=readTree(p.tree),t=trace({});let n0=0,n1=0,n2=0;for(let i=0;i<a.length;i++)if(a[i]!==null){const degree=Number(a[2*i+1]!=null)+Number(a[2*i+2]!=null);if(degree===0)n0++;else if(degree===1)n1++;else n2++;t.push(`结点 ${a[i]} 有 ${degree} 个孩子。`,{...treeView(a,[i]),line:1,vars:{n0,n1,n2}});}const last=a.findLastIndex(v=>v!==null),complete=a.slice(0,last+1).every(v=>v!==null);t.push(last<0?'空树没有叶结点，不能套用非空树的 n₀=n₂+1。':`n₀=${n0}，n₂=${n2}，满足 n₀=n₂+1；${complete?'是':'不是'}完全二叉树。`,{...treeView(a),line:3,result:{n0,n1,n2,complete,height:last<0?0:Math.floor(Math.log2(last+1))+1},vars:{height:last<0?0:Math.floor(Math.log2(last+1))+1,n:n0+n1+n2}});return t.frames;});
function traversal(p,mode){const a=readTree(p.tree),t=trace({}),out=[],visited=[];const visit=(i,stack)=>{out.push(a[i]);visited.push(i);t.push(`访问 ${a[i]}，加入输出序列。`,{...treeView(a,[i],visited),line:mode==='pre'?1:mode==='in'?2:mode==='post'?3:1,vars:{'输出':out.join(' → '),'辅助结构':stack.join(' → ')||'空'}});};t.push(`开始${{pre:'先序（根左右）',in:'中序（左根右）',post:'后序（左右根）',level:'层序（队列）'}[mode]}遍历。`,treeView(a));if(mode==='level'){const q=a[0]!=null?[0]:[];while(q.length){const i=q.shift();for(const c of [2*i+1,2*i+2])if(a[c]!=null)q.push(c);visit(i,q.map(x=>a[x]));}}else{const stack=[];function dfs(i){if(a[i]==null)return;stack.push(a[i]);t.push(`进入 ${a[i]} 的递归帧。`,{...treeView(a,[i],visited),line:0,vars:{'调用栈':stack.join(' → ')}});if(mode==='pre')visit(i,stack);dfs(2*i+1);if(mode==='in')visit(i,stack);dfs(2*i+2);if(mode==='post')visit(i,stack);stack.pop();t.push(`退出 ${a[i]} 的递归帧，返回双亲。`,{...treeView(a,[],visited),line:4,vars:{'调用栈':stack.join(' → ')||'空','输出':out.join(' → ')}});}dfs(0);}t.push(`遍历完成：${out.join(' → ')||'空树'}。`,{...treeView(a,[],visited),line:4,result:out,vars:{'输出':out.join(' → ')}});return t.frames;}
for(const mode of ['pre','in','post','level'])add('traversal',mode,{pre:'先序遍历',in:'中序遍历',post:'后序遍历',level:'层序遍历'}[mode],[treeField],mode==='level'?'根入队\n出队并访问；非空孩子按左、右入队\n重复直至队空\n每个结点仅入队一次\n返回访问序列':'进入非空结点\n先序：此处访问根\n递归左子树；中序：此处访问根\n递归右子树；后序：此处访问根\n返回双亲',p=>traversal(p,mode));
add('traversal','rebuild','先序 + 中序重建',[field('pre','先序','A B D E C F'),field('in','中序','D B E A C F','标签互异；最多 12 个结点')],'先序首项是根\n在中序中找到根，分出左右子树\n按左子树大小切分先序\n递归构造左右子树',p=>{const pre=p.pre.trim().split(/[,，\s]+/).filter(Boolean),ino=p.in.trim().split(/[,，\s]+/).filter(Boolean);if(pre.length>12||new Set(pre).size!==pre.length||pre.length!==ino.length||new Set(ino).size!==ino.length||pre.some(v=>!ino.includes(v)))throw Error('两序列须含相同的互异标签，且最多 12 项。');const t=trace({}),nodes=[],edges=[];function build(pr,ins,depth,l,r,parent){if(!pr.length)return;const root=pr[0],k=ins.indexOf(root);if(k<0)throw Error('先序与中序不一致，无法构造二叉树。');const id=root;nodes.push({id,label:root,x:(l+r)/2,y:45+depth*70});if(parent!=null)edges.push({from:parent,to:id});t.push(`先序首项 ${root} 为根，中序将其分成 [${ins.slice(0,k)}] 与 [${ins.slice(k+1)}]。`,{kind:'graph',nodes,edges,height:Math.max(350,depth*70+100),active:[id],line:1,vars:{'当前先序':pr.join(' '),'当前中序':ins.join(' ')}});build(pr.slice(1,k+1),ins.slice(0,k),depth+1,l,(l+r)/2,id);build(pr.slice(k+1),ins.slice(k+1),depth+1,(l+r)/2,r,id);}build(pre,ino,0,0,760,null);t.push('重建完成。这里用顺序扫描定位中序根，最坏 O(n²)；哈希索引可降为 O(n)。',{kind:'graph',nodes,edges,height:Math.max(350,...nodes.map(n=>n.y+70)),line:3,result:nodes.map(n=>n.label)});return t.frames;});
add('threaded','thread','中序线索化',[treeField],'中序遍历并维护 pre\n左孩子为空：ltag=1，指向前驱\n前驱的右孩子为空：rtag=1，指向当前\n首前驱和末后继为空；线索不是孩子',p=>{const a=readTree(p.tree),order=[],t=trace({}),threads=[],rows=[];function walk(i){if(a[i]==null)return;walk(2*i+1);order.push(i);walk(2*i+2);}walk(0);t.push(`中序次序是 ${order.map(i=>a[i]).join(' → ')}。`,treeView(a));order.forEach((i,k)=>{const prev=order[k-1],next=order[k+1],ltag=a[2*i+1]==null?1:0,rtag=a[2*i+2]==null?1:0;if(ltag&&prev!=null)threads.push({from:String(i),to:String(prev),dashed:true,curve:true,label:'前驱'});if(rtag&&next!=null)threads.push({from:String(i),to:String(next),dashed:true,curve:true,label:'后继'});rows.push([a[i],ltag,ltag?(a[prev]??'NULL'):a[2*i+1],rtag,rtag?(a[next]??'NULL'):a[2*i+2]]);t.push(`处理 ${a[i]}：仅将空孩子指针改成线索。`,{...treeView(a,[i],[],threads),line:ltag?1:2,table:{headers:['结点','ltag','left','rtag','right'],rows}});});t.push('虚线是前驱/后继线索，实线是孩子关系。遍历时必须检查 tag，不能把线索递归成子树。',{...treeView(a,[],[],threads),line:3,result:order.map(i=>a[i])});return t.frames;});
add('forest','convert','森林 → 孩子兄弟二叉树',[field('parents','双亲数组','-1, 0, 0, 1, 1, -1, 5','−1 表示根；其他双亲编号须小于本结点编号；最多10项')],'按双亲数组建立孩子列表\n每个结点仅保留指向第一个孩子的边\n兄弟之间用右指针连接\n森林的根也用右指针连接',p=>{const ps=numbers(p.parents,10);if(ps.some((v,i)=>!Number.isInteger(v)||v< -1||v>=i))throw Error('双亲须为 −1 或小于当前编号的有效编号。');const children=ps.map(()=>[]),roots=[];ps.forEach((v,i)=>v<0?roots.push(i):children[v].push(i));const nodes=ps.map((v,i)=>{let d=0,j=i;while(ps[j]>=0){d++;j=ps[j];}return {id:String(i),label:String(i),x:60+i*68,y:60+d*85};}),edges=ps.flatMap((v,i)=>v<0?[]:[{from:String(v),to:String(i)}]),t=trace({});t.push('原森林：同一个双亲可以拥有多个孩子。',{kind:'graph',nodes,edges,height:Math.max(350,...nodes.map(n=>n.y+65))});const converted=[];children.forEach((cs,i)=>{if(cs.length)converted.push({from:String(i),to:String(cs[0]),label:'左：孩子'});for(let k=1;k<cs.length;k++)converted.push({from:String(cs[k-1]),to:String(cs[k]),label:'右：兄弟'});t.push(`结点 ${i}：左指针指向 ${cs[0]??'NULL'}；孩子们用右指针依次相连。`,{kind:'graph',nodes,edges:[...converted],height:Math.max(350,...nodes.map(n=>n.y+65)),active:[String(i)],line:2});});for(let k=1;k<roots.length;k++)converted.push({from:String(roots[k-1]),to:String(roots[k]),label:'右：兄弟根'});t.push('转换完成，保留原布局便于比较。左指针表示第一个孩子，右指针表示下一个兄弟。',{kind:'graph',nodes,edges:converted,height:Math.max(350,...nodes.map(n=>n.y+65)),line:3,result:converted});return t.frames;});

function forestView(roots,active=[]){const nodes=[],edges=[];let cursor=0;const leafCount=n=>n.left?leafCount(n.left)+leafCount(n.right):1;const total=roots.reduce((n,r)=>n+leafCount(r),0);let max=0;function walk(n,d){max=Math.max(max,d);let x;if(n.left){const l=walk(n.left,d+1),r=walk(n.right,d+1);x=(l+r)/2;edges.push({from:n.id,to:n.left.id,label:'0'},{from:n.id,to:n.right.id,label:'1'});}else x=760*(cursor+++.5)/Math.max(1,total);nodes.push({id:n.id,label:String(n.w),sub:n.symbol??'',x,y:45+d*76});return x;}roots.forEach(r=>walk(r,0));return {kind:'graph',nodes,edges,active,height:Math.max(320,max*76+110)};}
add('huffman','build','构造哈夫曼树与编码',[field('weights','叶子权值','2, 3, 7, 9, 18','2～8 个正整数；相同权值按创建顺序打破平局')],'每个符号先成为一棵树\n选出权值最小的两棵树\n合并，父权值为两者之和\n重复至只剩一棵树；左0右1生成编码',p=>{const weights=numbers(p.weights,8);if(weights.length<2||weights.some(v=>v<=0||!Number.isInteger(v)))throw Error('请输入 2～8 个正整数权值。');let serial=0;const q=weights.map((w,i)=>({id:String(serial++),w,symbol:String.fromCharCode(65+i)})),t=trace({});t.push('每个符号对应一个叶结点。初始森林还没有编码。',forestView(q));while(q.length>1){q.sort((a,b)=>a.w-b.w||Number(a.id)-Number(b.id));const a=q[0],b=q[1];t.push(`选择最小的两个权值 ${a.w} 和 ${b.w}。`,{...forestView(q,[a.id,b.id]),line:1});q.splice(0,2,{id:String(serial++),w:a.w+b.w,left:a,right:b});t.push(`新父结点权值 ${a.w+b.w}，重新参与下一次比较。`,{...forestView(q,[q[0].id]),line:2});}let wpl=0;const codes=[];function walk(n,code){if(n.left){walk(n.left,code+'0');walk(n.right,code+'1');}else{wpl+=n.w*code.length;codes.push([n.symbol,n.w,code,code.length,n.w*code.length]);}}walk(q[0],'');t.push(`WPL = Σ(叶权值 × 路径边数) = ${wpl}。编码不唯一，但最优 WPL 相同。`,{...forestView(q),line:3,table:{headers:['符号','权','编码','长度','贡献'],rows:codes},result:{wpl,codes}});return t.frames;});
add('union-find','union','合并与路径压缩',[field('n','元素数量','7','1～10'),field('commands','操作序列','U 0 1; U 2 3; U 0 2; U 4 5; U 0 4; F 3','U a b 合并，F a 查找；分号分隔，最多20条')],'parent[root] 为负数，绝对值是集合大小\nFind 沿双亲链到根\n回溯时让经过的结点直接指根\nUnion 将较小集合接到较大集合的根',p=>{const n=integer(p.n,1,10,'元素数'),par=Array(n).fill(-1),t=trace({});const show=(note,active=[],line=0,result)=>{const roots=par.map((v,i)=>v<0?i:-1).filter(i=>i>=0),depth=i=>{let d=0;while(par[i]>=0){i=par[i];d++;}return d;};t.push(note,{kind:'graph',nodes:par.map((v,i)=>({id:String(i),label:String(i),x:55+i*70,y:60+depth(i)*85,sub:v<0?`根·大小${-v}`:''})),edges:par.flatMap((v,i)=>v<0?[]:[{from:String(i),to:String(v)}]),height:420,active:active.map(String),line,table:{headers:['元素',...par.map((_,i)=>i)],rows:[['parent',...par]]},vars:{'集合数量':roots.length},result});};show('初始化：每个元素是一个单元素集合。');function find(x){const route=[];let r=x;while(par[r]>=0){route.push(r);show(`查找 ${x}：从 ${r} 沿双亲指针到 ${par[r]}。`,[r,par[r]],1);r=par[r];}for(const v of route){par[v]=r;show(`路径压缩：令 parent[${v}]=${r}。`,[v,r],2);}return r;}const cmds=p.commands.split(/[;；\n]/).filter(s=>s.trim());if(cmds.length>20)throw Error('最多20条操作。');for(const cmd of cmds){const xs=cmd.trim().toUpperCase().split(/\s+/),op=xs[0];if(!['F','U'].includes(op)||xs.length!==(op==='F'?2:3))throw Error('格式为 U a b 或 F a。');let a=find(integer(xs[1],0,n-1,'元素'));if(op==='F'){show(`Find(${xs[1]}) = ${a}。`,[a],1,a);continue;}let b=find(integer(xs[2],0,n-1,'元素'));if(a===b){show('两个元素已属于同一集合，无需合并。',[a],3);continue;}if(par[a]>par[b])[a,b]=[b,a];par[a]+=par[b];par[b]=a;show(`将根 ${b} 接到根 ${a}，新集合大小 ${-par[a]}。`,[a,b],3);}show('操作完成。箭头由子结点指向双亲。按大小合并与路径压缩结合使用时具有近似常数的均摊复杂度。',[],3,[...par]);return t.frames;});

// Static lists keep physical slot identities stable across allocation and recycling.
function staticTrace(p,op){
 const input=numbers(p.values,10),cap=integer(p.capacity,1,12,'数据槽数');if(input.length>cap)throw Error('初始元素数超过可用数据槽。');
 const data=Array(cap+1).fill('·'),next=Array(cap+1).fill(-1),used=new Set();data[0]='head';next[0]=input.length?1:-1;
 input.forEach((v,i)=>{data[i+1]=v;next[i+1]=i+1<input.length?i+2:-1;used.add(i+1);});
 let free=input.length<cap?input.length+1:-1;for(let i=input.length+1;i<=cap;i++)next[i]=i<cap?i+1:-1;
 const t=trace({});const chain=()=>{const a=[];for(let i=next[0];i!==-1;i=next[i])a.push(i);return a;};
 function show(note,active=[],line=0,floating=null,result){const order=chain(),nodes=[{id:'0',label:'head',x:55,y:105,sub:'槽位 0'},...order.map((a,i)=>({id:String(a),label:String(data[a]),x:145+85*i,y:105,sub:`槽位 ${a}`}))],edges=[0,...order].flatMap(a=>next[a]===-1?[]:[{from:String(a),to:String(next[a])}]);if(floating!=null&&!order.includes(floating))nodes.push({id:String(floating),label:String(data[floating]),x:230,y:215,sub:`待接入/回收 · 槽 ${floating}`});t.push(note,{kind:'graph',nodes,edges,width:Math.max(760,180+order.length*85),height:300,active:active.map(String),line,vars:{'head.next':next[0],'备用链头 free':free,'长度':order.length},table:{headers:['槽位',...data.map((_,i)=>i)],rows:[['data',...data],['next',...next],['用途',...data.map((_,i)=>i===0?'头':used.has(i)?'数据':'备用')]]},caption:'槽位地址固定；只修改 next 游标。−1 表示空游标，槽位0为头结点，free指向备用链首槽。',result});}
 show('初始化数据链和备用链；两条链共用同一个数组。');
 const commands=op==='commands'?p.commands.split(/[;；\n]/).filter(s=>s.trim()):[op==='insert'?`I ${p.position} ${p.value}`:op==='delete'?`D ${p.position}`:`F ${p.value}`];if(commands.length>15)throw Error('最多 15 条操作。');
 for(const raw of commands){const xs=raw.trim().toUpperCase().split(/\s+/),cmd=xs[0],order=chain();if(!['I','D','F'].includes(cmd)||xs.length!==(cmd==='I'?3:2))throw Error('操作格式为 I 位序 值、D 位序 或 F 值。');if(cmd==='F'){const x=scalar(xs[1]);let found=0;for(let i=0;i<order.length;i++){show(`沿游标访问槽位 ${order[i]}，比较数据与 ${x}。`,[order[i]],1);if(data[order[i]]===x){found=i+1;break;}}show(found?`找到位序 ${found}，实际槽位 ${order[found-1]}。`:'未找到，返回 0。',[],3,null,found);continue;}
  const i=integer(xs[1],1,order.length+(cmd==='I'?1:0),'逻辑位序')-1,pred=i?order[i-1]:0;show(`定位前驱：逻辑位序 ${i}，实际槽位 ${pred}。`,[pred],1);
  if(cmd==='I'){if(free===-1){show('备用链为空，静态数组已满；插入失败，结构保持不变。',[],1,null,false);continue;}const slot=free;free=next[slot];data[slot]=scalar(xs[2]);next[slot]=next[pred];used.add(slot);show(`从备用链取出槽位 ${slot}，保存数据并令新槽的 next 指向原后继。`,[slot],2,slot);next[pred]=slot;show(`令前驱的 next=${slot}，接入完成。原有元素没有搬移。`,[pred,slot],3,null,chain().map(a=>data[a]));}
  else{const slot=order[i],deleted=data[slot];next[pred]=next[slot];show(`前驱绕过槽位 ${slot}，从数据链摘下待删槽。`,[pred,slot],2,slot);next[slot]=free;free=slot;data[slot]='·';used.delete(slot);show(`把槽位 ${slot} 放回备用链头；下次分配可重新使用它。删除值为 ${deleted}。`,[pred],3,null,chain().map(a=>data[a]));}
 }
 return t.frames;
}
labs['static-list']=[];
for(const op of ['insert','delete','find'])add('static-list',op,{insert:'分配槽位并插入',delete:'删除并回收槽位',find:'沿游标按值查找'}[op],[field('values','初始元素','12, 24, 36, 48, 60','最多 10 项'),field('capacity','可用数据槽数','8','不包含头结点槽位0；1～12'),...(op!=='find'?[pos]:[]),...(op!=='delete'?[val]:[])],'建立数据链与备用链\n定位逻辑位置 / 检查空满\n取用或回收物理槽位\n只修改游标，不搬移其他元素',p=>staticTrace(p,op));
add('static-list','commands','例题：删除后的槽位复用',[field('values','初始元素','10,20,30'),field('capacity','可用数据槽数','5'),field('commands','操作序列','D 2; I 1 99; I 3 77','I 位序 值：插入；D 位序：删除；F 值：查找；分号分隔')],'数据链与备用链共享数组\n沿游标定位前驱\n从 free 取槽 / 将删除槽归还 free\n更新前驱游标，保持物理地址不变',p=>staticTrace(p,'commands'));
add('traversal','iterative-in','非递归中序：显式栈',[treeField],'p 指向根，准备空栈\n沿左孩子链压栈，直到 p 为空\n弹栈并访问结点\np 转向其右孩子，继续循环',p=>{const a=readTree(p.tree),t=trace({}),stack=[],out=[],done=[];let cur=a[0]!=null?0:null;t.push('显式栈保存尚未完成中序访问的祖先结点。',treeView(a));while(cur!=null||stack.length){if(cur!=null){stack.push(cur);t.push(`压入 ${a[cur]}，继续寻找左孩子。`,{...treeView(a,[cur],done),line:1,vars:{'栈底→栈顶':stack.map(i=>a[i]).join(' → '),'输出':out.join(' → ')}});cur=a[2*cur+1]!=null?2*cur+1:null;}else{const i=stack.pop();out.push(a[i]);done.push(i);t.push(`左子树已处理完，弹出并访问 ${a[i]}。`,{...treeView(a,[i],done),line:2,vars:{'栈底→栈顶':stack.map(i=>a[i]).join(' → ')||'空','输出':out.join(' → ')}});cur=a[2*i+2]!=null?2*i+2:null;t.push(`转到 ${cur==null?'空右子树':`右孩子 ${a[cur]}`}。`,{...treeView(a,cur==null?[]:[cur],done),line:3});}}t.push(`中序结果 ${out.join(' → ')||'空'}；每个结点仅进栈、出栈一次。`,{...treeView(a,[],done),line:3,result:out});return t.frames;});
add('binary-tree','mirror','交换左右子树：镜像',[treeField],'后序处理每个结点\n先完成左右子树的镜像\n交换当前结点的左、右孩子\n返回镜像后的根',p=>{const a=readTree(p.tree),t=trace({}),nodes=a.map((label,i)=>label==null?null:{id:String(i),label,left:a[2*i+1]!=null?2*i+1:null,right:a[2*i+2]!=null?2*i+2:null});function view(active=[]){const ns=[],es=[];function walk(i,l,r,d){if(i==null)return;const n=nodes[i];ns.push({id:n.id,label:n.label,x:(l+r)/2,y:50+d*85});for(const [c,side]of [[n.left,'左'],[n.right,'右']])if(c!=null)es.push({from:n.id,to:nodes[c].id,label:side});walk(n.left,l,(l+r)/2,d+1);walk(n.right,(l+r)/2,r,d+1);}if(nodes[0])walk(0,0,760,0);return {kind:'graph',nodes:ns,edges:es,height:360,active:active.map(String)};}t.push('镜像交换的是孩子指针，不是交换结点数据。',view());function walk(i){if(i==null)return;const n=nodes[i];walk(n.left);walk(n.right);[n.left,n.right]=[n.right,n.left];t.push(`交换结点 ${n.label} 的左右孩子。`,{...view([i]),line:2});}if(nodes[0])walk(0);const pre=[];function collect(i){if(i==null)return;pre.push(nodes[i].label);collect(nodes[i].left);collect(nodes[i].right);}if(nodes[0])collect(0);t.push('所有结点的孩子指针交换完成。',{...view(),line:3,result:pre});return t.frames;});
add('stack-apps','two-stacks','两个栈实现一个队列',[field('commands','操作序列','E 10; E 20; D; E 30; D; D','E 值：入队；D：出队；分号分隔，最多15条')],'入队元素压入 in 栈\n出队时若 out 空，则逐个把 in 弹到 out\n从 out 栈顶弹出就是队头\n每个元素至多搬运一次，均摊 O(1)',p=>{const commands=p.commands.split(/[;；\n]/).filter(s=>s.trim());if(commands.length>15)throw Error('最多15条操作。');const ins=[],outs=[],logical=[],t=trace({}),result=[];const show=(note,line=0)=>t.push(note,{kind:'rows',rows:[{label:'in 栈（底 → 顶）',values:ins},{label:'out 栈（底 → 顶）',values:outs},{label:'逻辑队列（头 → 尾）',values:logical}],line});show('两个栈初始均为空。');for(const c of commands){const xs=c.trim().toUpperCase().split(/\s+/);if(xs[0]==='E'&&xs.length===2){ins.push(scalar(xs[1]));logical.push(scalar(xs[1]));show(`${xs[1]} 压入 in 栈，进入队尾。`,0);}else if(xs[0]==='D'&&xs.length===1){if(!outs.length)while(ins.length){const v=ins.pop();outs.push(v);show(`out 为空，将 ${v} 从 in 弹出并压入 out。搬运使元素顺序反转，但抽象队列次序保持不变。`,1);}if(outs.length){const v=outs.pop();logical.shift();result.push(v);show(`out 栈顶 ${v} 正是最早入队的元素，出队。`,2);}else show('两个栈都空，队空，不能出队。',2);}else throw Error('操作格式须为 E 数值 或 D。');}t.push(`出队序列：${result.join(' → ')||'无'}。只有 out 为空才搬运。`,{kind:'rows',rows:[{label:'in 栈',values:ins},{label:'out 栈',values:outs},{label:'已出队',values:result}],line:3,result});return t.frames;});

const vertex=i=>String.fromCharCode(65+i);
const graphFields=[field('n','顶点数量','6','2～8；按 A、B、C…命名，允许孤立顶点'),field('edges','边：起点 终点 权值','A B 4; A C 2; B C 1; B D 5; C D 8; C E 10; D E 2; D F 6; E F 3','分号分隔；权值可省略为1；不支持自环/重复边')];
const dagFields=[graphFields[0],field('edges','有向边：起点 终点 工期','A B 3; A C 2; B D 2; C D 4; C E 3; D F 3; E F 2')];
const sourceField=field('source','起点','A');
const directionField=field('directed','有向图？1 是 / 0 否','0');
function indexVertex(s,n){const v=s.trim().toUpperCase();if(!/^[A-H]$/.test(v)||v.charCodeAt(0)-65>=n)throw Error(`顶点须为 A～${vertex(n-1)}。`);return v.charCodeAt(0)-65;}
export function readGraph(p,directed=false){const n=integer(p.n,2,8,'顶点数'),edges=[],seen=new Set();for(const line of p.edges.split(/[;；\n]/).filter(s=>s.trim())){const items=line.trim().split(/[,，\s]+/);if(items.length<2||items.length>3)throw Error('边格式为 A B 4，用分号隔开多条边。');const u=indexVertex(items[0],n),v=indexVertex(items[1],n),w=items.length===3?scalar(items[2]):1;if(u===v)throw Error('本实验使用无自环的简单图。');const id=directed?`${u}-${v}`:[u,v].sort((a,b)=>a-b).join('-');if(seen.has(id))throw Error('不允许重复边。');seen.add(id);edges.push({u,v,w});}if(edges.length>24)throw Error('图示最多 24 条边。');return {n,vertices:Array.from({length:n},(_,i)=>i),edges,directed};}
const adjacency=g=>g.vertices.map(u=>g.edges.flatMap(e=>e.u===u?[{v:e.v,w:e.w}]:!g.directed&&e.v===u?[{v:e.u,w:e.w}]:[]).sort((a,b)=>a.v-b.v));
const weightText=x=>Number.isFinite(x)?x:'∞';
function graphView(g,active=[],done=[],chosen=[]){const keys=new Set(chosen.map(e=>`${e.u}-${e.v}`));return {kind:'graph',nodes:g.vertices.map((v,i)=>({id:String(v),label:vertex(v),x:380+260*Math.cos(2*Math.PI*i/g.vertices.length-Math.PI/2),y:175+130*Math.sin(2*Math.PI*i/g.vertices.length-Math.PI/2)})),edges:g.edges.map(e=>({from:String(e.u),to:String(e.v),label:String(e.w),undirected:!g.directed,curve:g.directed&&g.edges.some(f=>f.u===e.v&&f.v===e.u),hot:keys.has(`${e.u}-${e.v}`)||!g.directed&&keys.has(`${e.v}-${e.u}`)})),height:355,active:active.map(String),done:done.map(String),caption:`${g.directed?'有向':'无向'}带权图；邻居按字母升序访问；线上的数值是边权。`};}
function graphMatrix(g){return {headers:['',...g.vertices.map(vertex)],rows:g.vertices.map(i=>[vertex(i),...g.vertices.map(j=>i===j?0:weightText(g.edges.find(e=>e.u===i&&e.v===j||!g.directed&&e.v===i&&e.u===j)?.w??Infinity))])};}
for(const mode of ['represent','add-edge','remove-edge','add-vertex','remove-vertex'])add('graph-storage',mode,{represent:'查看四种存储表示','add-edge':'插入一条边','remove-edge':'删除一条边','add-vertex':'插入顶点','remove-vertex':'删除顶点'}[mode],[...graphFields,directionField,...(['add-edge','remove-edge'].includes(mode)?[field('from','起点 u','A'),field('to','终点 v','F'),...(mode==='add-edge'?[field('weight','边权','7')]:[])]:mode==='remove-vertex'?[field('from','删除顶点','C')]:[])],'读取顶点与边\n执行指定的存储 / 增删操作\n同步更新关联边\n检查邻接矩阵与邻接关系',p=>{const g=readGraph(p,integer(p.directed,0,1,'有向标志')===1),t=trace({});t.push('初始图。矩阵中 ∞ 表示无边，0 权边仍是有效边。',{...graphView(g),table:graphMatrix(g)});if(mode==='add-edge'||mode==='remove-edge'){const u=indexVertex(p.from,g.n),v=indexVertex(p.to,g.n);if(u===v)throw Error('简单图不支持自环。');const exists=g.edges.findIndex(e=>e.u===u&&e.v===v||!g.directed&&e.u===v&&e.v===u);if(mode==='add-edge'){if(exists>=0)throw Error('这条边已经存在，请先删除或选择另一对顶点。');g.edges.push({u,v,w:scalar(p.weight)});}else if(exists<0){t.push('该边不存在，图保持不变。',{...graphView(g),line:1});return t.frames;}else g.edges.splice(exists,1);t.push(`${mode==='add-edge'?'插入':'删除'}边 ${vertex(u)}${g.directed?'→':'—'}${vertex(v)}，${g.directed?'只更新对应方向':'对称更新两个矩阵单元'}。`,{...graphView(g,[u,v]),table:graphMatrix(g),line:2,result:g.edges});}else if(mode==='add-vertex'){if(g.n===8)throw Error('演示最多 8 个顶点。');g.vertices.push(g.n++);t.push(`增加孤立顶点 ${vertex(g.n-1)}：矩阵增加一行一列，邻接表增加一个表头。`,{...graphView(g,[g.n-1]),table:graphMatrix(g),line:2,result:g.vertices});}else if(mode==='remove-vertex'){const u=indexVertex(p.from,g.n);g.vertices=g.vertices.filter(v=>v!==u);g.edges=g.edges.filter(e=>e.u!==u&&e.v!==u);t.push(`删除 ${vertex(u)} 以及所有关联边，保留其他顶点标签。`,{...graphView(g),table:graphMatrix(g),line:2,result:g.edges});}else{t.push('邻接表为每个顶点保存出边（无向图保存关联边）；无向边在两个表中各出现一次。',{...graphView(g),line:1,table:{headers:['顶点','邻接点 : 权'],rows:g.vertices.map(v=>[vertex(v),adjacency(g)[v].map(e=>`${vertex(e.v)}:${e.w}`).join(' → ')||'∅'])}});t.push(g.directed?'十字链表：同一弧结点进入弧尾的出边链与弧头的入边链。':'邻接多重表：一条无向边只设一个边结点，并同时挂在两个端点的边链上。',{...graphView(g),line:2,table:{headers:g.directed?['弧','tailvex','headvex','tail端下一出弧','head端下一入弧']:['边','ivex','jvex','i端下一关联边','j端下一关联边'],rows:g.edges.map((e,k)=>{const next=(v,out)=>{const idx=g.edges.findIndex((f,j)=>j>k&&(g.directed?(out?f.u===v:f.v===v):f.u===v||f.v===v));return idx<0?'NULL':`e${idx}`;};return [`e${k}`,vertex(e.u),vertex(e.v),next(e.u,true),next(e.v,false)];})},caption:g.directed?'切换“有向图=0”可查看无向图的邻接多重表。':'切换“有向图=1”可查看有向图的十字链表。'});}return t.frames;});
function traverseGraph(p,mode){const g=readGraph(p,integer(p.directed,0,1,'有向标志')===1),adj=adjacency(g),s=indexVertex(p.source,g.n),seen=new Set(),out=[],chosen=[],dist=Array(g.n).fill(Infinity),t=trace({});dist[s]=0;const show=(note,u,q,line)=>t.push(note,{...graphView(g,[u],Array.from(seen),chosen),line,vars:{'输出':out.map(vertex).join(' → '),[mode==='bfs'?'队列':'递归栈']:q.map(vertex).join(' → ')||'空'},...(mode==='bfs'?{table:{headers:['顶点',...g.vertices.map(vertex)],rows:[['源点距离（边数）',...dist.map(weightText)]]}}:{})});t.push(`${mode==='bfs'?'广度':'深度'}优先遍历；遇到非连通部分时从最小未访问顶点继续。`,graphView(g));for(const r of [s,...g.vertices.filter(v=>v!==s)])if(!seen.has(r)){if(mode==='bfs'){seen.add(r);const q=[r];show(`顶点 ${vertex(r)} 入队并立即标记，避免重复入队。`,r,q,0);while(q.length){const u=q.shift();out.push(u);show(`出队并访问 ${vertex(u)}。`,u,q,1);for(const e of adj[u])if(!seen.has(e.v)){seen.add(e.v);q.push(e.v);dist[e.v]=dist[u]+1;chosen.push({u,v:e.v});show(`发现 ${vertex(e.v)}：入队并标记。`,e.v,q,2);}}}else{function dfs(u,stack){seen.add(u);out.push(u);show(`访问 ${vertex(u)}，沿最小的未访问邻居深入。`,u,stack,1);for(const e of adj[u])if(!seen.has(e.v)){chosen.push({u,v:e.v});dfs(e.v,[...stack,e.v]);}show(`顶点 ${vertex(u)} 的邻居已处理完，回溯。`,u,stack.slice(0,-1),2);}dfs(r,[r]);}}t.push(`遍历完成：${out.map(vertex).join(' → ')}。高亮边组成搜索森林。`,{...graphView(g,[],out,chosen),line:3,result:out.map(vertex),caption:mode==='bfs'?'距离忽略边权，仅表示源点到顶点的最少边数；∞ 表示从指定源点不可达。':'DFS 并不保证最短路径；访问次序由起点和邻居顺序共同决定。',...(mode==='bfs'?{table:{headers:['顶点',...g.vertices.map(vertex)],rows:[['最少边数',...dist.map(weightText)]]}}:{})});return t.frames;}
for(const mode of ['bfs','dfs'])add('graph-traverse',mode,mode==='bfs'?'BFS 与无权最短路':'DFS 与搜索森林',[...graphFields,directionField,sourceField],mode==='bfs'?'源点入队并标记\n队头出队，访问\n未访问邻居入队并标记\n队空后检查未访问分量':'从未访问顶点开始\n标记并访问，递归未访问邻居\n邻居处理完则回溯\n检查其他未访问分量',p=>traverseGraph(p,mode));
function mst(p,mode){const g=readGraph(p,false),t=trace({}),chosen=[];let total=0;t.push('最小生成树要求无向连通图；边权可为负。平权时按端点字母序确定演示次序。',graphView(g));if(mode==='prim'){const visited=new Set([indexVertex(p.source,g.n)]);while(visited.size<g.n){const options=g.edges.filter(e=>visited.has(e.u)!==visited.has(e.v)).sort((a,b)=>a.w-b.w||a.u-b.u||a.v-b.v);if(!options.length){t.push('找不到跨越当前集合的边：图不连通，不存在覆盖全部顶点的生成树。',{...graphView(g,[],[...visited],chosen),line:3,result:{connected:false,weight:total}});return t.frames;}const e=options[0];t.push(`在跨越割的边中选最小边 ${vertex(e.u)}—${vertex(e.v)}，权 ${e.w}。`,{...graphView(g,[e.u,e.v],[...visited],chosen),line:1});chosen.push(e);total+=e.w;visited.add(e.u);visited.add(e.v);t.push('把新顶点加入已覆盖集合。',{...graphView(g,[],[...visited],chosen),line:2,vars:{'累计权值':total,'边数':chosen.length}});}}else{const parent=g.vertices.map(i=>i);const root=x=>{while(parent[x]!==x)x=parent[x];return x;};const sorted=[...g.edges].sort((a,b)=>a.w-b.w||a.u-b.u||a.v-b.v);for(const e of sorted){const a=root(e.u),b=root(e.v);if(a===b)t.push(`跳过 ${vertex(e.u)}—${vertex(e.v)}：两端已连通，加入将成环。`,{...graphView(g,[e.u,e.v],[],chosen),line:1});else{parent[a]=b;chosen.push(e);total+=e.w;t.push(`接纳 ${vertex(e.u)}—${vertex(e.v)}（${e.w}），合并两个连通分量。`,{...graphView(g,[e.u,e.v],[],chosen),line:2,vars:{'累计权值':total,'边数':chosen.length}});}if(chosen.length===g.n-1)break;}}const connected=chosen.length===g.n-1;t.push(`${connected?'最小生成树':'图不连通，得到最小生成森林'}，总权值 ${total}。`,{...graphView(g,[],g.vertices,chosen),line:3,result:{connected,weight:total,edges:chosen}});return t.frames;}
for(const mode of ['prim','kruskal'])add('mst',mode,mode==='prim'?'Prim：扩展顶点集合':'Kruskal：按边合并',[...graphFields,...(mode==='prim'?[sourceField]:[])],mode==='prim'?'任选起点加入集合 S\n选 S 与外部之间最小权边\n把新顶点加入 S\n接纳 n−1 条边，或报告不连通':'按边权非递减排序\n用并查集判断两端是否同属一组\n不同组则接纳并合并\n接纳 n−1 条边，或得到生成森林',p=>mst(p,mode));
add('shortest','dijkstra','Dijkstra 单源最短路',[...graphFields,directionField,sourceField,field('target','查看到哪个顶点的路径','F')],'dist[source]=0，其余为∞\n从未确定顶点中选 dist 最小者\n确定该距离，尝试松弛每条出边\n重复直到全部确定或剩余不可达',p=>{const g=readGraph(p,integer(p.directed,0,1,'有向标志')===1);if(g.edges.some(e=>e.w<0))throw Error('Dijkstra 要求所有边权非负；含负边请使用 Floyd。');const s=indexVertex(p.source,g.n),target=indexVertex(p.target,g.n),d=Array(g.n).fill(Infinity),prev=Array(g.n).fill(null),done=[],adj=adjacency(g),t=trace({});d[s]=0;const table=()=>({headers:['顶点',...g.vertices.map(vertex)],rows:[['dist',...d.map(weightText)],['前驱',...prev.map(v=>v==null?'—':vertex(v))]]});t.push('只给源点距离 0，其余初始为 ∞。',{...graphView(g,[s]),table:table()});while(done.length<g.n){const u=g.vertices.filter(v=>!done.includes(v)).sort((a,b)=>d[a]-d[b]||a-b)[0];if(!Number.isFinite(d[u]))break;done.push(u);t.push(`确定 ${vertex(u)} 的最短距离为 ${d[u]}。`,{...graphView(g,[u],done),line:1,table:table()});for(const e of adj[u])if(!done.includes(e.v)){const candidate=d[u]+e.w;if(candidate<d[e.v]){d[e.v]=candidate;prev[e.v]=u;t.push(`松弛 ${vertex(u)}→${vertex(e.v)}：${d[u]}+${e.w}=${candidate} 更小，更新距离和前驱。`,{...graphView(g,[u,e.v],done,[{u,v:e.v}]),line:2,table:table()});}else t.push(`检查 ${vertex(u)}→${vertex(e.v)}：候选距离 ${candidate} 不更优，保持不变。`,{...graphView(g,[u,e.v],done),line:2,table:table()});}}const path=[];if(Number.isFinite(d[target])){let v=target;while(v!=null){path.unshift(v);v=prev[v];}}const chosen=path.slice(1).map((v,i)=>({u:path[i],v}));t.push(path.length?`到 ${vertex(target)} 的最短路：${path.map(vertex).join(' → ')}，距离 ${d[target]}。`:`${vertex(target)} 从源点不可达。`,{...graphView(g,[],done,chosen),line:3,table:table(),result:{dist:d,path:path.map(vertex)}});return t.frames;});
add('shortest','floyd','Floyd 全源最短路',[...graphFields,directionField],'D 初始化为边权，主对角为0\n外层枚举允许的中间顶点 k\nD[i][j]=min(D[i][j],D[i][k]+D[k][j])\n若 D[v][v]<0 则有负权环',p=>{const g=readGraph(p,integer(p.directed,0,1,'有向标志')===1),d=g.vertices.map(i=>g.vertices.map(j=>i===j?0:Infinity)),t=trace({});g.edges.forEach(e=>{d[e.u][e.v]=e.w;if(!g.directed)d[e.v][e.u]=e.w;});const table=()=>({headers:['',...g.vertices.map(vertex)],rows:d.map((r,i)=>[vertex(i),...r.map(weightText)])});t.push('初始距离矩阵；允许负边，但最短路要求不存在负权环。',{...graphView(g),table:table()});for(let k=0;k<g.n;k++){t.push(`现在允许 ${vertex(k)} 作为新的中间顶点；k 必须放在最外层循环。`,{...graphView(g,[k]),table:table(),line:1,vars:{k:vertex(k)}});for(let i=0;i<g.n;i++)for(let j=0;j<g.n;j++)if(d[i][k]+d[k][j]<d[i][j]){const old=d[i][j];d[i][j]=d[i][k]+d[k][j];t.push(`${vertex(i)}→${vertex(j)} 经过 ${vertex(k)} 更短：${weightText(old)} → ${d[i][j]}。`,{...graphView(g,[i,k,j]),table:table(),line:2,vars:{i:vertex(i),j:vertex(j),k:vertex(k)}});if(d.some((r,i)=>r[i]<0)){t.push('发现负权环：某个主对角距离小于 0，相关最短路没有有限最小值。',{...graphView(g),table:table(),line:3,result:{negativeCycle:true}});return t.frames;}}}t.push('得到所有顶点对间的最短距离；∞ 表示不可达。',{...graphView(g),table:table(),line:3,result:{negativeCycle:false,dist:d}});return t.frames;});
function topological(g){const indeg=Array(g.n).fill(0),adj=adjacency(g),q=[],order=[];g.edges.forEach(e=>indeg[e.v]++);indeg.forEach((d,i)=>{if(d===0)q.push(i);});while(q.length){q.sort((a,b)=>a-b);const u=q.shift();order.push(u);for(const e of adj[u])if(--indeg[e.v]===0)q.push(e.v);}return order;}
add('dag','topo','拓扑排序与环检测',dagFields,'计算所有顶点入度\n选择字母最小的零入度顶点输出\n删除其出边，将新零入度点加入候选\n输出不足 n 个则存在有向环',p=>{const g=readGraph(p,true),indeg=Array(g.n).fill(0),out=[],adj=adjacency(g),t=trace({});g.edges.forEach(e=>indeg[e.v]++);const table=()=>({headers:['顶点',...g.vertices.map(vertex)],rows:[['当前入度',...indeg]]});t.push('顶点表示任务，边表示先后约束；边权不参与拓扑排序。',{...graphView(g),table:table()});let unique=true;while(out.length<g.n){const available=g.vertices.filter(v=>indeg[v]===0&&!out.includes(v));if(!available.length)break;if(available.length>1)unique=false;const u=available[0];out.push(u);t.push(`零入度候选为 ${available.map(vertex).join('、')}，选择 ${vertex(u)}。`,{...graphView(g,[u],out),line:1,table:table(),vars:{'输出':out.map(vertex).join(' → ')}});for(const e of adj[u]){indeg[e.v]--;t.push(`移除 ${vertex(u)}→${vertex(e.v)} 的约束，${vertex(e.v)} 的入度减为 ${indeg[e.v]}。`,{...graphView(g,[e.v],out,[{u,v:e.v}]),line:2,table:table()});}}t.push(out.length<g.n?'没有零入度顶点但仍有顶点未输出：存在有向环。':`拓扑排序完成。${unique?'每一步只有一个候选，因此序列唯一。':'存在多种合法序列；本次按字母序选择。'}`,{...graphView(g,[],out),line:3,table:table(),result:{order:out.map(vertex),cycle:out.length<g.n,unique:out.length===g.n&&unique}});return t.frames;});
add('dag','expression','表达式 DAG 共享子表达式',[field('operator','顶层运算符：+ 或 *','+'),''].filter(Boolean),'表达式 (a+b) op (a+b)\n先建立叶子 a、b\n将重复子表达式 a+b 合并为一个结点\n两个使用位置指向同一个子表达式',p=>{if(!['+','*'].includes(p.operator.trim()))throw Error('运算符只能为 + 或 *。');const op=p.operator.trim(),t=trace({}),nodes=[{id:'root',label:op,x:380,y:50},{id:'sum',label:'+',x:380,y:150},{id:'a',label:'a',x:260,y:260},{id:'b',label:'b',x:500,y:260}];t.push(`表达式为 (a+b) ${op} (a+b)。两次 a+b 可以共享同一个结点。`,{kind:'graph',nodes,edges:[],height:340});t.push('先建立共享子表达式 a+b。',{kind:'graph',nodes,edges:[{from:'sum',to:'a',label:'左'},{from:'sum',to:'b',label:'右'}],height:340,line:1});t.push('顶层的左右两个操作数都引用同一个 + 结点。图中两条弧分别代表左右操作数。',{kind:'graph',nodes,edges:[{from:'sum',to:'a',label:'左'},{from:'sum',to:'b',label:'右'},{from:'root',to:'sum',label:'左操作数',curve:true},{from:'root',to:'sum',label:'右操作数',curve:true,reverse:true}],height:340,line:3,result:4});return t.frames;});
add('critical','critical','AOE 网：关键路径',dagFields.map(f=>f.key==='edges'?{...f,hint:'工期为非负整数，边用分号分隔'}:f),'拓扑排序，检查无环和非负工期\n正向：ve[v]=max(ve[v],ve[u]+w)\n工期=max(ve)；逆向计算 vl[u]=min(vl[u],vl[v]−w)\n活动 e=ve[u]，l=vl[v]−w；e=l 为关键活动',p=>{const g=readGraph(p,true);if(g.edges.some(e=>e.w<0||!Number.isInteger(e.w)))throw Error('关键路径演示的活动工期须为非负整数。');const order=topological(g);if(order.length<g.n)throw Error('AOE 网必须无环，请先用拓扑排序定位环。');const adj=adjacency(g),ve=Array(g.n).fill(0),vl=Array(g.n).fill(Infinity),t=trace({});const table=()=>({headers:['事件',...g.vertices.map(vertex)],rows:[['ve',...ve],['vl',...vl.map(weightText)]]});t.push('顶点是事件，边是活动。多源/多汇统一按虚拟起终点的 0 工期边处理。',{...graphView(g),table:table()});for(const u of order)for(const e of adj[u]){ve[e.v]=Math.max(ve[e.v],ve[u]+e.w);t.push(`正向：ve[${vertex(e.v)}] = max(原值, ${ve[u]}+${e.w}) = ${ve[e.v]}。`,{...graphView(g,[u,e.v]),table:table(),line:1});}const duration=Math.max(...ve);vl.fill(duration);t.push(`总工期为 ${duration}。所有事件最迟时间先设为总工期。`,{...graphView(g),table:table(),line:2});for(const u of order.toReversed())for(const e of adj[u]){vl[u]=Math.min(vl[u],vl[e.v]-e.w);t.push(`逆向：vl[${vertex(u)}] = min(原值, ${vl[e.v]}−${e.w}) = ${vl[u]}。`,{...graphView(g,[u,e.v]),table:table(),line:2});}const chosen=g.edges.filter(e=>ve[e.u]===vl[e.v]-e.w),activities=g.edges.map(e=>[`${vertex(e.u)}→${vertex(e.v)}`,e.w,ve[e.u],vl[e.v]-e.w,vl[e.v]-e.w-ve[e.u],ve[e.u]===vl[e.v]-e.w?'关键':'非关键']);t.push(`总工期 ${duration}；高亮所有零时差活动。它们可能组成多条关键路径。`,{...graphView(g,[],[],chosen),table:{headers:['活动','工期','最早 e','最迟 l','时差','结论'],rows:activities},line:3,result:{duration,ve,vl,critical:chosen}});return t.frames;});
